def _pre_ident(ident):
    # Numeric identifiers sort before alphanumeric ones; compare by value/text.
    if ident.isdigit():
        return (0, int(ident), "")
    return (1, 0, ident)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if pre:
        # Pre-release: rank 0, ordered by its dot-separated identifiers.
        return (nums, 0, tuple(_pre_ident(p) for p in pre.split(".")))
    # Release: rank 1, so it sorts after any pre-release of the same core.
    return (nums, 1, ())

